  function setLanguage(language) {
    if (!dictionaries[language]) language = "en";
    document.documentElement.lang = language;
    var dictionary = dictionaries[language];
    var walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
    var node;
    while ((node = walker.nextNode())) {
      if (node.__alykeySource === undefined) node.__alykeySource = node.nodeValue;
      var source = node.__alykeySource.trim();
      if (!source) continue;
      var translated = dictionary[source] || (serviceTranslations[language] && serviceTranslations[language][source]);
      node.nodeValue = node.__alykeySource.replace(source, translated || source);
    }
    document.querySelectorAll("[data-language]").forEach(function (button) {
      var active = button.dataset.language === language;
      if (active) button.setAttribute("aria-current", "true");
      else button.removeAttribute("aria-current");
    });
    var secondHomeUrls = {
      en: "property-care-second-homes-alicante.html",
      es: "cuidado-segunda-residencia-alicante.html",
      fr: "entretien-residence-secondaire-alicante.html",
      uk: "dohliad-za-druhym-zhytlom-alicante.html"
    };
    document.querySelectorAll("[data-second-home-link]").forEach(function (link) {
      link.setAttribute("href", secondHomeUrls[language] || secondHomeUrls.en);
    });
    document.querySelectorAll("[placeholder], [aria-label], [title]").forEach(function (el) {
      ["placeholder", "aria-label", "title"].forEach(function (attribute) {
        if (!el.hasAttribute(attribute)) return;
        var dataKey = "i18n" + attribute.charAt(0).toUpperCase() + attribute.slice(1);
        if (!el.dataset[dataKey]) el.dataset[dataKey] = el.getAttribute(attribute);
        var source = el.dataset[dataKey];
        el.setAttribute(attribute, dictionary[source] || source);
      });
    });
    var title = document.querySelector("title");
    if (title) {
      if (!title.dataset.i18nSource) title.dataset.i18nSource = title.textContent;
      title.textContent = dictionary[title.dataset.i18nSource] || (serviceTranslations[language] && serviceTranslations[language][title.dataset.i18nSource]) || title.dataset.i18nSource;
    }
    document.querySelectorAll('meta[name="description"]').forEach(function (meta) {
      if (!meta.dataset.i18nSource) meta.dataset.i18nSource = meta.content;
      meta.content = (metadata[language] && metadata[language][meta.dataset.i18nSource]) || (serviceTranslations[language] && serviceTranslations[language][meta.dataset.i18nSource]) || meta.dataset.i18nSource;
    });
    var ogTitle = document.querySelector('meta[property="og:title"]');
    if (ogTitle && title) ogTitle.content = title.textContent;
    var ogDescription = document.querySelector('meta[property="og:description"]');
    var pageDescription = document.querySelector('meta[name="description"]');
    if (ogDescription && pageDescription) ogDescription.content = pageDescription.content;
    var ogLocale = document.querySelector('meta[property="og:locale"]');
    if (ogLocale) ogLocale.content = { en: "en_GB", es: "es_ES", fr: "fr_FR", uk: "uk_UA" }[language] || "en_GB";
    try { localStorage.setItem("alykey-language", language); } catch (_) {}
    document.dispatchEvent(new CustomEvent("alykey:languagechange", { detail: { language: language } }));
  }

  document.addEventListener("DOMContentLoaded", function () {
    document.querySelectorAll("[data-language]").forEach(function (button) {
      button.addEventListener("click", function () { setLanguage(button.dataset.language); });
    });
    var saved = "en";
    try { saved = localStorage.getItem("alykey-language") || "en"; } catch (_) {}
    setLanguage(saved);
  });
